#[test]
fn translates_basic_chat_completion() {
    let req = OpenAIChatCompletionRequest {
        model: "gpt-4o".into(),
        messages: vec![
            ChatMessage {
                role: "system".into(),
                content: Value::String("You are helpful.".into()),
                name: None,
                tool_call_id: None,
                tool_calls: None,
            },
            ChatMessage {
                role: "user".into(),
                content: Value::String("Hello".into()),
                name: None,
                tool_call_id: None,
                tool_calls: None,
            },
        ],
        max_tokens: Some(100),
        max_completion_tokens: None,
        temperature: Some(0.5),
        top_p: None,
        frequency_penalty: None,
        presence_penalty: None,
        logit_bias: None,
        seed: None,
        stream: None,
        stop: None,
        tools: None,
        tool_choice: None,
        reasoning_effort: None,
        reasoning: None,
        response_format: None,
        parallel_tool_calls: None,
        n: None,
        modalities: None,
        audio: None,
        logprobs: None,
        top_logprobs: None,
        safety_identifier: None,
        stream_options: None,
        user: None,
    };
    let body = chat_completion_to_anthropic(&req);
    // The requested model is preserved verbatim; nothing rewrites it.
    assert_eq!(body["model"], "gpt-4o");
    assert_eq!(body["max_tokens"], 100);
    assert_eq!(body["temperature"], 0.5);
    assert_eq!(body["system"], "You are helpful.");
    let msgs = body["messages"].as_array().unwrap();
    assert_eq!(msgs.len(), 1);
    assert_eq!(msgs[0]["role"], "user");
    assert_eq!(msgs[0]["content"], "Hello");
}

