            {"prompt_cache_breakpoint": {"mode": "explicit"}},
            {"prompt_cache_breakpoint": {"mode": "explicit"}},
            {"prompt_cache_breakpoint": {"mode": "explicit"}}
        ]}]}),
    ] {
        assert!(crate::bridge_controls::validate_openai_prompt_cache(&unsupported, true).is_err());
    }

    let chat = json!({
        "model": "gpt", "messages": [{"role": "user", "content": [{
            "type": "text", "text": "hello",
            "prompt_cache_breakpoint": {"mode": "explicit"}
